def compute(vars):
    contribution_2015 = vars["v1"]
    contribution_2014 = vars["v2"]

    if contribution_2014 == 0:
        return None

    ratio = contribution_2015 / contribution_2014
    return {
        "value": ratio,
        "trace": {
            "contribution_2015": contribution_2015,
            "contribution_2014": contribution_2014,
            "output_meta": {
                "currency": None,
                "scale": "ones",
                "unit": "ratio"
            }
        }
    }
